	MONT_ADD(t0, t1, t2, v0, v1, v2);
	MONT_ADD(t0, t1, t2, w0, w1, w2);
	MONT_DBL(s0, s1, s2);
	MONT_ADD(t0, t1, t2, s0, s1, s2);
	u[2] = t0 * n0;
	MONT_MAC(t0, t1, t2, u[2], m[0]);
	t0 = t1;
	t1 = t2;
	t2 = 0;
	/* column 3 */
	MONT_MUL(s0, s1, s2, a[0], a[3]);
	MONT_MUL(c0, c1, c2, a[1], a[2]);
	MONT_MAC(t0, t1, t2, u[0], m[3]);
	MONT_MUL(v0, v1, v2, u[1], m[2]);
	MONT_MUL(w0, w1, w2, u[2], m[1]);
	MONT_ADD(t0, t1, t2, v0, v1, v2);
	MONT_ADD(t0, t1, t2, w0, w1, w2);
	MONT_ADD(s0, s1, s2, c0, c1, c2);
	MONT_DBL(s0, s1, s2);
	MONT_ADD(t0, t1, t2, s0, s1, s2);
	u[3] = t0 * n0;
	MONT_MAC(t0, t1, t2, u[3], m[0]);
	t0 = t1;
	t1 = t2;
	t2 = 0;
	/* column 4 */
	MONT_MUL(s0, s1, s2, a[0], a[4]);
	MONT_MUL(c0, c1, c2, a[1], a[3]);
	MONT_MAC(t0, t1, t2, a[2], a[2]);
	MONT_MUL(v0, v1, v2, u[0], m[4]);
