	MONT_MUL(c0, c1, c2, a[1], a[4]);
	MONT_MAC(s0, s1, s2, a[2], a[3]);
	MONT_MAC(t0, t1, t2, u[0], m[5]);
	MONT_MUL(v0, v1, v2, u[1], m[4]);
